def flood(g):
    h,w=len(g),len(g[0]); cnt=Counter(c for row in g for c in row); bg=cnt.most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    stack=[(i,j) for i in range(h) for j in range(w) if g[i][j]==bg and (i in(0,h-1) or j in(0,w-1))]
    for a,b in stack: seen[a][b]=True
    import collections
    q=collections.deque(stack)
    while q:
        a,b=q.popleft()
        for da in(-1,0,1):
            for db in(-1,0,1):
                if da==db==0: continue
                x,y=a+da,b+db
                if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==bg:
                    seen[x][y]=True; q.append((x,y))
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=1
    return out
